// Error Trigger payload: execution context, not the original webhook body.
// Record what is actually available rather than inventing a domain.

const e = $input.first().json;
const err = e.execution?.error ?? {};

return [{
  json: {
    domain: 'unknown',
    idempotency_key: null,
    failure_stage: 'unknown',
    last_error: String(err.message ?? 'unhandled workflow failure').slice(0, 4000),
    attempt_count: 1,
    payload_snapshot: JSON.stringify({
      source: 'error_workflow_safety_net',
      workflow: e.workflow ?? null,
      execution_id: e.execution?.id ?? null,
      execution_url: e.execution?.url ?? null,
      last_node_executed: e.execution?.lastNodeExecuted ?? null,
      mode: e.execution?.mode ?? null,
      error_name: err.name ?? null,
      error_node: err.node?.name ?? null,
    }),
  },
}];
